WITH docs AS (SELECT value AS doc FROM jsonb_array_elements($authored$[{"case_key":"bank-legal-2026-126","title":"Льгота за партийный билет","category":"Правовая практика","situation":"Муниципальный совет хочет освободить от земельного налога только членов одной партии. Экономическое или социальное основание категории не объяснено.\n\nПроект льготы охватывает партийные земельные участки независимо от назначения и стоимости. Владельцы аналогичных участков без партийного членства остаются плательщиками. Пояснительная записка содержит только обещание поддержки сторонникам. Участник рассматривает проект муниципального акта до голосования и должен оценить основание выделенной категории.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Не вводить дискриминационную партийную льготу; формировать допустимые категории в пределах налоговой компетенции, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Освободить от земельного налога только членов одной партии, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Не вводить дискриминационную партийную льготу; формировать допустимые категории в пределах налоговой компетенции. Основание: НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Не вводить дискриминационную партийную льготу; формировать допустимые категории в пределах налоговой компетенции. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Освободить от земельного налога только членов одной партии. Надлежащий шаг: Не вводить дискриминационную партийную льготу; формировать допустимые категории в пределах налоговой компетенции. Основание: НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Освободить от земельного налога только членов одной партии. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"}]},"comic_scene":{"scene_id":"scene-176","title":"Льгота за партийный билет","case_key":"bank-legal-2026-126","format":"animated-svg","version":4,"alt":"Льгота за партийный билет: участники изучают выбор и протокол и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Льгота за партийный билет»: Муниципальный совет хочет освободить от земельного налога только членов одной партии. Экономическое или социальное основание категории не объяснено."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, статьи 3, 56 и глава 31; Конституция РФ, статья 19.. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-127","title":"Региональный запрет торговли","category":"Правовая практика","situation":"Региональное министерство письмом полностью запретило продажу законно обращающегося товара на территории субъекта, не имея законного полномочия на такой запрет.\n\nТовар разрешён к обороту при соблюдении федеральных требований, нарушений этих требований проверка не установила. Министерство направило торговым сетям письмо с требованием убрать его за три дня. В письме нет ссылки на предоставленное законом полномочие вводить такой запрет. Участнику нужно выбрать действие по письму и обращениям продавцов.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Проверить федеральные основания и компетенцию; не устанавливать ведомственным письмом незаконное препятствие экономической деятельности, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Запретить законный товар региональным письмом без полномочия, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить федеральные основания и компетенцию; не устанавливать ведомственным письмом незаконное препятствие экономической деятельности. Основание: Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить федеральные основания и компетенцию; не устанавливать ведомственным письмом незаконное препятствие экономической деятельности. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Запретить законный товар региональным письмом без полномочия. Надлежащий шаг: Проверить федеральные основания и компетенцию; не устанавливать ведомственным письмом незаконное препятствие экономической деятельности. Основание: Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Запретить законный товар региональным письмом без полномочия. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-177","title":"Региональный запрет торговли","case_key":"bank-legal-2026-127","format":"animated-svg","version":4,"alt":"Региональный запрет торговли: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Региональный запрет торговли»: Региональное министерство письмом полностью запретило продажу законно обращающегося товара на территории субъекта, не имея законного полномочия на такой запрет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статьи 34 и 74; Федеральный закон № 135-ФЗ.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-128","title":"Конкурентная аренда земли","category":"Правовая практика","situation":"Администрация хочет без предусмотренного основания передать публичный участок знакомому предпринимателю. Другие желающие предложили участвовать в открытой процедуре.\n\nНа участок претендуют три предпринимателя, все предлагают допустимое использование. Знакомый администрации заявитель просит прямую аренду по письму поддержки, специальных оснований для этого в досье нет. Проект договора подготовлен до проверки способа предоставления. Участник получает кадастровые сведения и заявки; решение требуется перед отправкой договора.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Определить законное основание и процедуру предоставления участка; при отсутствии исключения провести требуемые торги, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Передать публичный участок знакомому без требуемой процедуры, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Определить законное основание и процедуру предоставления участка; при отсутствии исключения провести требуемые торги. Основание: Земельный кодекс РФ, порядок предоставления публичных земель. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Определить законное основание и процедуру предоставления участка; при отсутствии исключения провести требуемые торги. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Земельный кодекс РФ, порядок предоставления публичных земель. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Земельный кодекс РФ, порядок предоставления публичных земель. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Земельный кодекс РФ, порядок предоставления публичных земель. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Земельный кодекс РФ, порядок предоставления публичных земель. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Передать публичный участок знакомому без требуемой процедуры. Надлежащий шаг: Определить законное основание и процедуру предоставления участка; при отсутствии исключения провести требуемые торги. Основание: Земельный кодекс РФ, порядок предоставления публичных земель. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Передать публичный участок знакомому без требуемой процедуры. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"Земельный кодекс РФ, порядок предоставления публичных земель. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-178","title":"Конкурентная аренда земли","case_key":"bank-legal-2026-128","format":"animated-svg","version":4,"alt":"Конкурентная аренда земли: участники изучают правовой режим земли и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Конкурентная аренда земли»: Администрация хочет без предусмотренного основания передать публичный участок знакомому предпринимателю. Другие желающие предложили участвовать в открытой процедуре."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Земельный кодекс РФ, порядок предоставления публичных земель.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-129","title":"Стройка на территории памятника","category":"Правовая практика","situation":"Застройщик начал земляные работы в охранной зоне объекта культурного наследия без необходимого согласования. Муниципалитет обещает узаконить всё актом приёмки здания.\n\nЭкскаватор начал земляные работы в границах охранной зоны, которые нанесены на официальную схему. У застройщика есть общий строительный пакет, но необходимое согласование для этой территории не представлено. Письмо муниципалитета обещает оформить результаты после завершения здания. Участник оценивает начало работ и полномочия предложенного подписанта.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр культуры","глава"],"decision_options":["Проверить охранные требования и согласования до работ; приёмка не заменяет предусмотренные разрешительные процедуры, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Узаконить земляные работы у памятника будущим актом приёмки, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить охранные требования и согласования до работ; приёмка не заменяет предусмотренные разрешительные процедуры. Основание: Федеральный закон № 73-ФЗ; градостроительное законодательство. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр культуры, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить охранные требования и согласования до работ; приёмка не заменяет предусмотренные разрешительные процедуры. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр культуры","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 73-ФЗ; градостроительное законодательство. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр культуры","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 73-ФЗ; градостроительное законодательство. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр культуры","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 73-ФЗ; градостроительное законодательство. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр культуры","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 73-ФЗ; градостроительное законодательство. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Узаконить земляные работы у памятника будущим актом приёмки. Надлежащий шаг: Проверить охранные требования и согласования до работ; приёмка не заменяет предусмотренные разрешительные процедуры. Основание: Федеральный закон № 73-ФЗ; градостроительное законодательство. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр культуры, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Узаконить земляные работы у памятника будущим актом приёмки. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр культуры","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 73-ФЗ; градостроительное законодательство. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-179","title":"Стройка на территории памятника","case_key":"bank-legal-2026-129","format":"animated-svg","version":4,"alt":"Стройка на территории памятника: участники изучают инфраструктура и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Стройка на территории памятника»: Застройщик начал земляные работы в охранной зоне объекта культурного наследия без необходимого согласования. Муниципалитет обещает узаконить всё актом приёмки здания."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 73-ФЗ; градостроительное законодательство.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-130","title":"Экологический платёж вместо разрешения","category":"Правовая практика","situation":"Предприятие утверждает, что уплата экологического платежа позволяет ему нарушать установленные условия выбросов. Условия разрешительной документации не соблюдены.\n\nВ отчёте предприятия указаны фактические выбросы выше согласованных условий. Платёж перечислен, и бухгалтер приложил квитанцию как объяснение продолжения работы без изменений. Экологический специалист отдельно составил акт о несоблюдении условий. Участнику переданы разрешительная документация, отчёт и платёж; необходимо определить значение каждого документа.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр природ","министр эколог","глава"],"decision_options":["Разграничить платёж и соблюдение экологических требований; уплата не легализует нарушение допустимых условий деятельности, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Считать экологический платёж разрешением нарушать условия выбросов, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разграничить платёж и соблюдение экологических требований; уплата не легализует нарушение допустимых условий деятельности. Основание: Федеральный закон № 7-ФЗ «Об охране окружающей среды». Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр природ, министр эколог, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разграничить платёж и соблюдение экологических требований; уплата не легализует нарушение допустимых условий деятельности. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр природ","министр эколог","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 7-ФЗ «Об охране окружающей среды». Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр природ","министр эколог","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 7-ФЗ «Об охране окружающей среды». Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр природ","министр эколог","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 7-ФЗ «Об охране окружающей среды». Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр природ","министр эколог","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 7-ФЗ «Об охране окружающей среды». Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Считать экологический платёж разрешением нарушать условия выбросов. Надлежащий шаг: Разграничить платёж и соблюдение экологических требований; уплата не легализует нарушение допустимых условий деятельности. Основание: Федеральный закон № 7-ФЗ «Об охране окружающей среды». Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр природ, министр эколог, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Считать экологический платёж разрешением нарушать условия выбросов. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр природ","министр эколог","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 7-ФЗ «Об охране окружающей среды». Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-180","title":"Экологический платёж вместо разрешения","case_key":"bank-legal-2026-130","format":"animated-svg","version":4,"alt":"Экологический платёж вместо разрешения: участники изучают бюджетное основание и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Экологический платёж вместо разрешения»: Предприятие утверждает, что уплата экологического платежа позволяет ему нарушать установленные условия выбросов. Условия разрешительной документации не соблюдены."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 7-ФЗ «Об охране окружающей среды».. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-131","title":"Доступ к правосудию через начальника","category":"Правовая практика","situation":"Канцелярия суда отказывает в приёме обращения, пока заявитель не получит согласие руководителя учреждения, чьи действия он оспаривает.\n\nЗаявитель оспаривает отказ учреждения, подписанный его руководителем. В канцелярии требуют разрешение этого же руководителя на обращение в суд. Форма заявления и приложенные документы отвечают установленным требованиям приёма. Участник рассматривает действия канцелярии до истечения срока обращения заявителя.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Оценить обращение по процессуальным требованиям; согласие оспариваемого органа не является условием судебной защиты, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Не принять иск без согласия органа, действия которого оспариваются, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Оценить обращение по процессуальным требованиям; согласие оспариваемого органа не является условием судебной защиты. Основание: Конституция РФ, статья 46; процессуальные требования к обращению в суд. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Оценить обращение по процессуальным требованиям; согласие оспариваемого органа не является условием судебной защиты. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 46; процессуальные требования к обращению в суд. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 46; процессуальные требования к обращению в суд. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 46; процессуальные требования к обращению в суд. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 46; процессуальные требования к обращению в суд. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Не принять иск без согласия органа, действия которого оспариваются. Надлежащий шаг: Оценить обращение по процессуальным требованиям; согласие оспариваемого органа не является условием судебной защиты. Основание: Конституция РФ, статья 46; процессуальные требования к обращению в суд. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Не принять иск без согласия органа, действия которого оспариваются. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статья 46; процессуальные требования к обращению в суд. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-181","title":"Доступ к правосудию через начальника","case_key":"bank-legal-2026-131","format":"animated-svg","version":4,"alt":"Доступ к правосудию через начальника: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Доступ к правосудию через начальника»: Канцелярия суда отказывает в приёме обращения, пока заявитель не получит согласие руководителя учреждения, чьи действия он оспаривает."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статья 46; процессуальные требования к обращению в суд.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-132","title":"Доказательство из слухов","category":"Правовая практика","situation":"Орган основывает неблагоприятное решение только на анонимном пересказе. Проверяемых обстоятельств и иных доказательств нет, заявителю не дали представить объяснения.\n\nАнонимное сообщение содержит обвинение, но не указывает проверяемые даты, документы или свидетелей. Неблагоприятное решение готовят без ознакомления адресата с материалами. В досье нет дополнительных результатов проверки. Участнику необходимо оценить, какие факты установлены и какое решение возможно на представленном основании.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Установить и проверить юридически значимые факты, дать предусмотренную возможность представить позицию и мотивировать решение, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Вынести неблагоприятное решение только по анонимным слухам, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Установить и проверить юридически значимые факты, дать предусмотренную возможность представить позицию и мотивировать решение. Основание: Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Установить и проверить юридически значимые факты, дать предусмотренную возможность представить позицию и мотивировать решение. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Вынести неблагоприятное решение только по анонимным слухам. Надлежащий шаг: Установить и проверить юридически значимые факты, дать предусмотренную возможность представить позицию и мотивировать решение. Основание: Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Вынести неблагоприятное решение только по анонимным слухам. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-182","title":"Доказательство из слухов","case_key":"bank-legal-2026-132","format":"animated-svg","version":4,"alt":"Доказательство из слухов: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Доказательство из слухов»: Орган основывает неблагоприятное решение только на анонимном пересказе. Проверяемых обстоятельств и иных доказательств нет, заявителю не дали представить объяснения."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статьи 19 и 46; правила соответствующей административной процедуры.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-133","title":"Обязательное примирение без согласия","category":"Правовая практика","situation":"Посредник обещает завершить спор медиацией и подписывает соглашение за стороны, которые не выражали согласия на его условия.\n\nСтороны обсуждали медиацию, но одна из них отклонила предложенную сумму выплаты. Посредник направил им подписанное только им соглашение и объявил спор завершённым. Полномочий подписывать за стороны ему не выдавали. Участник получает переписку и документ; нужно оценить его значение для дальнейшего урегулирования.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Соблюсти добровольность и полномочия подписантов; посредник не подменяет волеизъявление сторон, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Подписать медиативное соглашение за несогласные стороны, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Соблюсти добровольность и полномочия подписантов; посредник не подменяет волеизъявление сторон. Основание: Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Соблюсти добровольность и полномочия подписантов; посредник не подменяет волеизъявление сторон. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Подписать медиативное соглашение за несогласные стороны. Надлежащий шаг: Соблюсти добровольность и полномочия подписантов; посредник не подменяет волеизъявление сторон. Основание: Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Подписать медиативное соглашение за несогласные стороны. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-183","title":"Обязательное примирение без согласия","case_key":"bank-legal-2026-133","format":"animated-svg","version":4,"alt":"Обязательное примирение без согласия: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Обязательное примирение без согласия»: Посредник обещает завершить спор медиацией и подписывает соглашение за стороны, которые не выражали согласия на его условия."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 193-ФЗ, добровольность медиации; ГК РФ, представительство.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-134","title":"Срок обращения и уважительная причина","category":"Правовая практика","situation":"Заявитель пропустил процессуальный срок из-за подтверждённой длительной госпитализации. Секретарь предлагает навсегда закрыть доступ без рассмотрения ходатайства.\n\nГоспитализация длилась 35 дней и полностью охватывала заключительный период срока обращения. Заявитель приложил медицинские документы и ходатайство о восстановлении срока. Канцелярия предлагает вернуть весь комплект без передачи судье. Участник должен определить движение заявления и ходатайства с учётом документированных обстоятельств.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Рассмотреть надлежащее ходатайство и доказательства причины по применимому процессуальному закону; не решать вопрос отказом канцелярии, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Отказать в рассмотрении ходатайства о восстановлении срока в канцелярии, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Рассмотреть надлежащее ходатайство и доказательства причины по применимому процессуальному закону; не решать вопрос отказом канцелярии. Основание: Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Рассмотреть надлежащее ходатайство и доказательства причины по применимому процессуальному закону; не решать вопрос отказом канцелярии. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Отказать в рассмотрении ходатайства о восстановлении срока в канцелярии. Надлежащий шаг: Рассмотреть надлежащее ходатайство и доказательства причины по применимому процессуальному закону; не решать вопрос отказом канцелярии. Основание: Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Отказать в рассмотрении ходатайства о восстановлении срока в канцелярии. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-184","title":"Срок обращения и уважительная причина","case_key":"bank-legal-2026-134","format":"animated-svg","version":4,"alt":"Срок обращения и уважительная причина: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Срок обращения и уважительная причина»: Заявитель пропустил процессуальный срок из-за подтверждённой длительной госпитализации. Секретарь предлагает навсегда закрыть доступ без рассмотрения ходатайства."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Соответствующий процессуальный кодекс, восстановление процессуальных сроков; Конституция РФ, статья 46.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-135","title":"Банкротство и один любимый кредитор","category":"Правовая практика","situation":"Руководитель неплатёжеспособного предприятия выводит оставшиеся средства на погашение долга аффилированной компании, оставляя остальных кредиторов без имущества.\n\nНа счёте предприятия осталось 3 млн ₽ при обязательствах перед несколькими кредиторами на 11 млн ₽. Руководитель подготовил платёж аффилированной компании, срок требования которой не имеет очевидного преимущества. Остальные кредиторы уже направили требования, процедура несостоятельности обсуждается. Участник оценивает платёж до списания последнего доступного имущества.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Оценить признаки неплатёжеспособности, обязанности руководителя и возможное предпочтение; действовать в предусмотренной процедуре, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Погасить только аффилированного кредитора в обход банкротной процедуры, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Оценить признаки неплатёжеспособности, обязанности руководителя и возможное предпочтение; действовать в предусмотренной процедуре. Основание: Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Оценить признаки неплатёжеспособности, обязанности руководителя и возможное предпочтение; действовать в предусмотренной процедуре. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Погасить только аффилированного кредитора в обход банкротной процедуры. Надлежащий шаг: Оценить признаки неплатёжеспособности, обязанности руководителя и возможное предпочтение; действовать в предусмотренной процедуре. Основание: Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Погасить только аффилированного кредитора в обход банкротной процедуры. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-185","title":"Банкротство и один любимый кредитор","case_key":"bank-legal-2026-135","format":"animated-svg","version":4,"alt":"Банкротство и один любимый кредитор: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Банкротство и один любимый кредитор»: Руководитель неплатёжеспособного предприятия выводит оставшиеся средства на погашение долга аффилированной компании, оставляя остальных кредиторов без имущества."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 127-ФЗ, оспаривание сделок и предпочтение кредитору.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-136","title":"Наследство и неподписанное обещание","category":"Правовая практика","situation":"После смерти владельца родственник предъявил переписку «квартира будет твоей» и требует оформить всё имущество в обход остальных наследников.\n\nВ переписке владелец обсуждал намерение передать квартиру родственнику, но отдельного оформленного распоряжения в досье нет. После смерти обнаружены также другие наследники и сведения об имуществе. Родственник просит оформить право немедленно, не уведомляя остальных. Участник рассматривает представленные материалы в рамках открытия наследственного дела.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Установить основание наследования и действительность распоряжения; бытовое обещание не заменяет законную форму завещания, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Передать наследство по бытовому обещанию вместо установленного основания, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Установить основание наследования и действительность распоряжения; бытовое обещание не заменяет законную форму завещания. Основание: ГК РФ, часть третья, наследование и форма завещания. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Установить основание наследования и действительность распоряжения; бытовое обещание не заменяет законную форму завещания. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, часть третья, наследование и форма завещания. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, часть третья, наследование и форма завещания. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, часть третья, наследование и форма завещания. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, часть третья, наследование и форма завещания. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Передать наследство по бытовому обещанию вместо установленного основания. Надлежащий шаг: Установить основание наследования и действительность распоряжения; бытовое обещание не заменяет законную форму завещания. Основание: ГК РФ, часть третья, наследование и форма завещания. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Передать наследство по бытовому обещанию вместо установленного основания. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, часть третья, наследование и форма завещания. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-186","title":"Наследство и неподписанное обещание","case_key":"bank-legal-2026-136","format":"animated-svg","version":4,"alt":"Наследство и неподписанное обещание: участники изучают текст и права и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Наследство и неподписанное обещание»: После смерти владельца родственник предъявил переписку «квартира будет твоей» и требует оформить всё имущество в обход остальных наследников."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, часть третья, наследование и форма завещания.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-137","title":"Договор с несовершеннолетним","category":"Правовая практика","situation":"Магазин продал пятнадцатилетнему дорогую технику в кредит без необходимого согласия законного представителя. Продавец считает любой договор ребёнка безусловно действительным.\n\nСтоимость покупки составляет 110 тыс. ₽, оплата оформлена как обязательство на двенадцать месяцев. У продавца есть возраст покупателя, но отсутствуют документы о требуемом согласии или полной дееспособности. Законный представитель узнал о договоре после первого платёжного уведомления. Участник должен оценить характер сделки и заявленные последствия.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Проверить возраст, вид сделки, объём самостоятельной дееспособности и необходимое согласие; не приравнивать любую покупку к мелкой бытовой сделке, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Считать любую кредитную покупку пятнадцатилетнего мелкой бытовой сделкой, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить возраст, вид сделки, объём самостоятельной дееспособности и необходимое согласие; не приравнивать любую покупку к мелкой бытовой сделке. Основание: ГК РФ, статьи 26 и 175. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить возраст, вид сделки, объём самостоятельной дееспособности и необходимое согласие; не приравнивать любую покупку к мелкой бытовой сделке. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 26 и 175. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 26 и 175. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 26 и 175. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 26 и 175. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Считать любую кредитную покупку пятнадцатилетнего мелкой бытовой сделкой. Надлежащий шаг: Проверить возраст, вид сделки, объём самостоятельной дееспособности и необходимое согласие; не приравнивать любую покупку к мелкой бытовой сделке. Основание: ГК РФ, статьи 26 и 175. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Считать любую кредитную покупку пятнадцатилетнего мелкой бытовой сделкой. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, статьи 26 и 175. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-187","title":"Договор с несовершеннолетним","case_key":"bank-legal-2026-137","format":"animated-svg","version":4,"alt":"Договор с несовершеннолетним: участники изучают инфраструктура и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Договор с несовершеннолетним»: Магазин продал пятнадцатилетнему дорогую технику в кредит без необходимого согласия законного представителя. Продавец считает любой договор ребёнка безусловно действительным."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, статьи 26 и 175.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-138","title":"Благоустройство без слушаний","category":"Правовая практика","situation":"Администрация меняет документ территориального планирования, для которого предусмотрена публичная процедура. Она заменила её опросом подписчиков в своём канале.\n\nИзменение предусматривает размещение объекта рядом с жилым кварталом и затрагивает несколько участков. В электронном опросе участвовали подписчики канала, часть жителей о нём не знала. Официальные материалы публичной процедуры и протокол обсуждения не подготовлены. Участник рассматривает проект изменения до его утверждения представительным органом.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Провести предусмотренную для конкретного документа процедуру; опрос в канале может дополнять, но не заменять её, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Заменить обязательное публичное обсуждение опросом подписчиков, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Провести предусмотренную для конкретного документа процедуру; опрос в канале может дополнять, но не заменять её. Основание: Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Провести предусмотренную для конкретного документа процедуру; опрос в канале может дополнять, но не заменять её. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Заменить обязательное публичное обсуждение опросом подписчиков. Надлежащий шаг: Провести предусмотренную для конкретного документа процедуру; опрос в канале может дополнять, но не заменять её. Основание: Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Заменить обязательное публичное обсуждение опросом подписчиков. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Градостроительный кодекс РФ, общественные обсуждения и публичные слушания. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-188","title":"Благоустройство без слушаний","case_key":"bank-legal-2026-138","format":"animated-svg","version":4,"alt":"Благоустройство без слушаний: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Благоустройство без слушаний»: Администрация меняет документ территориального планирования, для которого предусмотрена публичная процедура. Она заменила её опросом подписчиков в своём канале."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Градостроительный кодекс РФ, общественные обсуждения и публичные слушания.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-139","title":"Публичное обещание компенсации","category":"Правовая практика","situation":"Пресс-секретарь обещал всем жителям компенсацию без утверждённого порядка и бюджетного основания. Социальная служба получила массовые заявления.\n\nПосле выступления пресс-секретаря поступило 240 заявлений о выплате по 20 тыс. ₽. В бюджете нет соответствующего основания, условия и круг получателей не утверждены. Сотрудники социальной службы предлагают начать платежи по записи трансляции. Участнику доступны обещание, заявления и бюджет; нужно организовать официальный ответ и дальнейшие действия.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Определить законное расходное обязательство и процедуру, объяснить действующие основания; пресс-обещание само по себе не заменяет акт, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Выдать пресс-обещание за достаточное основание новой выплаты, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Определить законное расходное обязательство и процедуру, объяснить действующие основания; пресс-обещание само по себе не заменяет акт. Основание: БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Определить законное расходное обязательство и процедуру, объяснить действующие основания; пресс-обещание само по себе не заменяет акт. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Выдать пресс-обещание за достаточное основание новой выплаты. Надлежащий шаг: Определить законное расходное обязательство и процедуру, объяснить действующие основания; пресс-обещание само по себе не заменяет акт. Основание: БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Выдать пресс-обещание за достаточное основание новой выплаты. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, расходные обязательства; применимое законодательство о социальной поддержке. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"}]},"comic_scene":{"scene_id":"scene-189","title":"Публичное обещание компенсации","case_key":"bank-legal-2026-139","format":"animated-svg","version":4,"alt":"Публичное обещание компенсации: участники изучают бюджетное основание и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Публичное обещание компенсации»: Пресс-секретарь обещал всем жителям компенсацию без утверждённого порядка и бюджетного основания. Социальная служба получила массовые заявления."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, расходные обязательства; применимое законодательство о социальной поддержке.. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-140","title":"Национальность как основание отказа","category":"Правовая практика","situation":"Муниципальное предприятие отказывает в обычной услуге исключительно из-за национальности клиента, хотя необходимые документы и основания имеются.\n\nКлиент представил тот же комплект документов, который принимают у остальных заявителей услуги. Сотрудник письменно указал единственной причиной отказа национальность клиента. Специального правового основания ограничения в досье нет. Участник рассматривает жалобу и условия оказания услуги перед направлением официального ответа.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Применить равные законные условия доступа; этническое происхождение не является основанием такого отказа, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Отказать в обычной услуге по этническому происхождению клиента, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Применить равные законные условия доступа; этническое происхождение не является основанием такого отказа. Основание: Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Применить равные законные условия доступа; этническое происхождение не является основанием такого отказа. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Отказать в обычной услуге по этническому происхождению клиента. Надлежащий шаг: Применить равные законные условия доступа; этническое происхождение не является основанием такого отказа. Основание: Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Отказать в обычной услуге по этническому происхождению клиента. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статья 19; ГК РФ, публичный договор и защита права. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-190","title":"Гражданство как условие частного договора","case_key":"bank-legal-2026-140","format":"animated-svg","version":4,"alt":"Гражданство как условие частного договора: участники изучают обязательства сторон и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Гражданство как условие частного договора»: Муниципальное предприятие отказывает в обычной услуге исключительно из-за национальности клиента, хотя необходимые документы и основания имеются."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статья 19; ГК РФ, публичный договор и защита права.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-141","title":"Личная переписка для служебного отчёта","category":"Правовая практика","situation":"Руководитель публикует личную переписку сотрудника в открытом отчёте, объясняя это интересом аудитории. Согласия и законного основания раскрытия нет.\n\nПереписка получена из личного аккаунта и касается семейных обстоятельств сотрудника. Руководитель вставил скриншоты в проект открытого отчёта без согласия и указания законного основания. Отчёт ещё не опубликован, но доступен редактору сайта. Участник должен оценить необходимость раскрытия и порядок обработки данного материала.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Исключить неправомерное раскрытие, отделить служебные факты от охраняемой частной информации и обеспечить законное основание обработки, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Опубликовать частную переписку без законного основания, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Исключить неправомерное раскрытие, отделить служебные факты от охраняемой частной информации и обеспечить законное основание обработки. Основание: Конституция РФ, статьи 23–24; законодательство о персональных данных. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Исключить неправомерное раскрытие, отделить служебные факты от охраняемой частной информации и обеспечить законное основание обработки. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 23–24; законодательство о персональных данных. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 23–24; законодательство о персональных данных. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 23–24; законодательство о персональных данных. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 23–24; законодательство о персональных данных. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Опубликовать частную переписку без законного основания. Надлежащий шаг: Исключить неправомерное раскрытие, отделить служебные факты от охраняемой частной информации и обеспечить законное основание обработки. Основание: Конституция РФ, статьи 23–24; законодательство о персональных данных. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Опубликовать частную переписку без законного основания. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статьи 23–24; законодательство о персональных данных. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-191","title":"Личная переписка для служебного отчёта","case_key":"bank-legal-2026-141","format":"animated-svg","version":4,"alt":"Личная переписка для служебного отчёта: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Личная переписка для служебного отчёта»: Руководитель публикует личную переписку сотрудника в открытом отчёте, объясняя это интересом аудитории. Согласия и законного основания раскрытия нет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статьи 23–24; законодательство о персональных данных.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-142","title":"Чужое фото в партийной программе","category":"Правовая практика","situation":"Партия включила чужую фотографию в печатную программу, не получив права использования. Указание автора она считает полноценной лицензией.\n\nФотограф разместил снимок в портфолио с условиями использования, отдельного разрешения партия не получала. Макет программы предусматривает печать 2 тыс. экземпляров и публикацию файла в сети. Дизайнер указал имя автора под изображением и считает вопрос закрытым. Участник получает макет и условия; решение требуется до заказа тиража.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["руководитель партии","депутат","министр юстиции"],"decision_options":["Проверить права и условия использования, получить разрешение либо применить законное исключение; подпись автора не заменяет лицензию, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Считать имя фотографа в подписи полноценной лицензией на фото, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить права и условия использования, получить разрешение либо применить законное исключение; подпись автора не заменяет лицензию. Основание: ГК РФ, часть четвёртая, авторские права и допустимое использование. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: руководитель партии, депутат, министр юстиции. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить права и условия использования, получить разрешение либо применить законное исключение; подпись автора не заменяет лицензию. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["руководитель партии","депутат","министр юстиции"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, часть четвёртая, авторские права и допустимое использование. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["руководитель партии","депутат","министр юстиции"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, часть четвёртая, авторские права и допустимое использование. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["руководитель партии","депутат","министр юстиции"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, часть четвёртая, авторские права и допустимое использование. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["руководитель партии","депутат","министр юстиции"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, часть четвёртая, авторские права и допустимое использование. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Считать имя фотографа в подписи полноценной лицензией на фото. Надлежащий шаг: Проверить права и условия использования, получить разрешение либо применить законное исключение; подпись автора не заменяет лицензию. Основание: ГК РФ, часть четвёртая, авторские права и допустимое использование. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: руководитель партии, депутат, министр юстиции. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Считать имя фотографа в подписи полноценной лицензией на фото. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["руководитель партии","депутат","министр юстиции"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, часть четвёртая, авторские права и допустимое использование. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-192","title":"Чужое фото в партийной программе","case_key":"bank-legal-2026-142","format":"animated-svg","version":4,"alt":"Чужое фото в партийной программе: участники изучают выбор и протокол и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Чужое фото в партийной программе»: Партия включила чужую фотографию в печатную программу, не получив права использования. Указание автора она считает полноценной лицензией."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, часть четвёртая, авторские права и допустимое использование.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-143","title":"Секретный отзыв разрешения","category":"Правовая практика","situation":"Орган отозвал разрешение предпринимателя, не указав основание и не предоставив предусмотренную возможность возражений. Причину обещают сообщить после закрытия деятельности.\n\nПредприниматель получил уведомление об отзыве, которое не содержит мотивов и порядка представления возражений. Деятельность требуют прекратить через два дня, материалы основания пока не раскрыты. В досье предусмотренная процедура участия адресата не проведена. Участник оценивает документ до наступления указанного срока.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Проверить законные основания и обязательную процедуру; оформить мотивированное решение и доступные способы обжалования, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Отозвать разрешение без мотивировки и предусмотренной процедуры, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить законные основания и обязательную процедуру; оформить мотивированное решение и доступные способы обжалования. Основание: Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить законные основания и обязательную процедуру; оформить мотивированное решение и доступные способы обжалования. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Отозвать разрешение без мотивировки и предусмотренной процедуры. Надлежащий шаг: Проверить законные основания и обязательную процедуру; оформить мотивированное решение и доступные способы обжалования. Основание: Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Отозвать разрешение без мотивировки и предусмотренной процедуры. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-193","title":"Секретный отзыв разрешения","case_key":"bank-legal-2026-143","format":"animated-svg","version":4,"alt":"Секретный отзыв разрешения: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Секретный отзыв разрешения»: Орган отозвал разрешение предпринимателя, не указав основание и не предоставив предусмотренную возможность возражений. Причину обещают сообщить после закрытия деятельности."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статьи 34 и 46; закон, регулирующий соответствующее разрешение.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-144","title":"Две ответственности за один эпизод","category":"Правовая практика","situation":"Два должностных лица одного органа независимо вынесли постановления по одному административному эпизоду в отношении того же лица. Оба постановления предполагают одинаковое наказание.\n\nОба постановления относятся к одному времени, месту, действию и одному привлекаемому лицу. Второй инспектор не проверил наличие первого решения в журнале органа. Заявитель представил обе копии и просит устранить двойное требование об оплате. Участник должен сопоставить эпизоды и определить дальнейшее действие по материалам.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Проверить тождество эпизода и наличие постановления; исключить повторную административную ответственность за одно нарушение, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Назначить второе одинаковое наказание за один эпизод, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить тождество эпизода и наличие постановления; исключить повторную административную ответственность за одно нарушение. Основание: КоАП РФ, статьи 4.1 и 24.5. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить тождество эпизода и наличие постановления; исключить повторную административную ответственность за одно нарушение. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 4.1 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 4.1 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 4.1 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 4.1 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Назначить второе одинаковое наказание за один эпизод. Надлежащий шаг: Проверить тождество эпизода и наличие постановления; исключить повторную административную ответственность за одно нарушение. Основание: КоАП РФ, статьи 4.1 и 24.5. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Назначить второе одинаковое наказание за один эпизод. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"КоАП РФ, статьи 4.1 и 24.5. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-194","title":"Две ответственности за один эпизод","case_key":"bank-legal-2026-144","format":"animated-svg","version":4,"alt":"Две ответственности за один эпизод: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Две ответственности за один эпизод»: Два должностных лица одного органа независимо вынесли постановления по одному административному эпизоду в отношении того же лица. Оба постановления предполагают одинаковое наказание."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. КоАП РФ, статьи 4.1 и 24.5.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-145","title":"Изменение подсудности распоряжением","category":"Правовая практика","situation":"Начальник ведомства решил, что все споры с его органом будет рассматривать выбранная им комиссия вместо суда. Заявителям рассылают обязательное распоряжение.\n\nВ распоряжении указано, что жалобы и судебные заявления граждан сначала должна окончательно разрешать ведомственная комиссия. Члены комиссии назначаются руководителем ответчика, независимого судебного рассмотрения документ не предусматривает. Заявителю отказали в направлении документов со ссылкой на распоряжение. Участник оценивает компетенцию органа и установленный способ защиты.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["судья","суд"],"decision_options":["Соблюсти законную подсудность и порядок защиты; ведомственное распоряжение не лишает права на предусмотренный суд, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Заменить предусмотренный законом суд ведомственной комиссией, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Соблюсти законную подсудность и порядок защиты; ведомственное распоряжение не лишает права на предусмотренный суд. Основание: Конституция РФ, статьи 46–47; процессуальное законодательство. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Соблюсти законную подсудность и порядок защиты; ведомственное распоряжение не лишает права на предусмотренный суд. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 46–47; процессуальное законодательство. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 46–47; процессуальное законодательство. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 46–47; процессуальное законодательство. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статьи 46–47; процессуальное законодательство. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Заменить предусмотренный законом суд ведомственной комиссией. Надлежащий шаг: Соблюсти законную подсудность и порядок защиты; ведомственное распоряжение не лишает права на предусмотренный суд. Основание: Конституция РФ, статьи 46–47; процессуальное законодательство. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: судья, суд. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Заменить предусмотренный законом суд ведомственной комиссией. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["судья","суд"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статьи 46–47; процессуальное законодательство. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-195","title":"Изменение подсудности распоряжением","case_key":"bank-legal-2026-145","format":"animated-svg","version":4,"alt":"Изменение подсудности распоряжением: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Изменение подсудности распоряжением»: Начальник ведомства решил, что все споры с его органом будет рассматривать выбранная им комиссия вместо суда. Заявителям рассылают обязательное распоряжение."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статьи 46–47; процессуальное законодательство.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-146","title":"Лишняя справка для услуги","category":"Правовая практика","situation":"Центр госуслуг требует у заявителя справку, которую орган обязан получить межведомственно, и отказывается регистрировать заявление до её представления.\n\nЗапрошенная справка находится в государственном реестре и должна поступать по межведомственному каналу. Заявитель представил обязательные документы, а оператор требует принести справку лично на бумаге. Регистрация обращения откладывается, что влияет на дату предоставления услуги. Участник проверяет перечень и порядок обмена сведениями до отказа в приёме.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Принять заявление по надлежащему комплекту и использовать межведомственное взаимодействие, если закон не требует документ от заявителя, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Отказать в регистрации заявления без справки, получаемой межведомственно, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Принять заявление по надлежащему комплекту и использовать межведомственное взаимодействие, если закон не требует документ от заявителя. Основание: Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Принять заявление по надлежащему комплекту и использовать межведомственное взаимодействие, если закон не требует документ от заявителя. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Отказать в регистрации заявления без справки, получаемой межведомственно. Надлежащий шаг: Принять заявление по надлежащему комплекту и использовать межведомственное взаимодействие, если закон не требует документ от заявителя. Основание: Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Отказать в регистрации заявления без справки, получаемой межведомственно. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-196","title":"Лишняя справка для услуги","case_key":"bank-legal-2026-146","format":"animated-svg","version":4,"alt":"Лишняя справка для услуги: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Лишняя справка для услуги»: Центр госуслуг требует у заявителя справку, которую орган обязан получить межведомственно, и отказывается регистрировать заявление до её представления."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 210-ФЗ, требования к предоставлению государственных и муниципальных услуг.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-147","title":"Реквизиция без компенсации","category":"Правовая практика","situation":"Для устранения последствий чрезвычайной ситуации орган изымает имущество и объявляет, что возврат или компенсация никогда не предусмотрены.\n\nВ чрезвычайной ситуации использован грузовой автомобиль частного владельца для доставки материалов. Орган зафиксировал изъятие, но в акте написал, что оценка стоимости, компенсация и последующий возврат исключены. Собственник просит сведения о состоянии автомобиля и основании дальнейшего удержания. Участник рассматривает акт и требования владельца после завершения срочных работ.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Проверить законные условия реквизиции, оценку и компенсацию, а также право на судебную защиту и возврат сохранившегося имущества, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Исключить компенсацию и судебную защиту при реквизиции, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить законные условия реквизиции, оценку и компенсацию, а также право на судебную защиту и возврат сохранившегося имущества. Основание: ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить законные условия реквизиции, оценку и компенсацию, а также право на судебную защиту и возврат сохранившегося имущества. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Исключить компенсацию и судебную защиту при реквизиции. Надлежащий шаг: Проверить законные условия реквизиции, оценку и компенсацию, а также право на судебную защиту и возврат сохранившегося имущества. Основание: ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Исключить компенсацию и судебную защиту при реквизиции. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, статья 242; законодательство о чрезвычайных ситуациях. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-197","title":"Реквизиция без компенсации","case_key":"bank-legal-2026-147","format":"animated-svg","version":4,"alt":"Реквизиция без компенсации: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Реквизиция без компенсации»: Для устранения последствий чрезвычайной ситуации орган изымает имущество и объявляет, что возврат или компенсация никогда не предусмотрены."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, статья 242; законодательство о чрезвычайных ситуациях.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-148","title":"Государственная помощь без контроля","category":"Правовая практика","situation":"Получатель субсидии выполнил основную работу, но отказался от обязательной отчётности. Куратор предлагает не фиксировать нарушение, чтобы не ухудшать показатель ведомства.\n\nСоглашение о субсидии устанавливает отчёт о результатах, расходах и подтверждающих документах. Основной объект введён, но получатель письменно отказался представить обязательный отчёт в срок. Куратор предлагает отметить полный результат без материалов проверки. Участник должен выбрать действие для отчётности и контроля до закрытия периода.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Проверить условия и отчётность, документировать нарушение и применить предусмотренные меры; ведомственный показатель не отменяет контроль, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Не фиксировать отсутствие обязательной отчётности по субсидии, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить условия и отчётность, документировать нарушение и применить предусмотренные меры; ведомственный показатель не отменяет контроль. Основание: БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Защита репутации финансового органа через предусмотренный контроль. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить условия и отчётность, документировать нарушение и применить предусмотренные меры; ведомственный показатель не отменяет контроль. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Защита репутации финансового органа через предусмотренный контроль.","legal_basis":"БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита репутации финансового органа через предусмотренный контроль.","legal_basis":"БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита репутации финансового органа через предусмотренный контроль.","legal_basis":"БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Защита репутации финансового органа через предусмотренный контроль.","legal_basis":"БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Не фиксировать отсутствие обязательной отчётности по субсидии. Надлежащий шаг: Проверить условия и отчётность, документировать нарушение и применить предусмотренные меры; ведомственный показатель не отменяет контроль. Основание: БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Не фиксировать отсутствие обязательной отчётности по субсидии. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"}]},"comic_scene":{"scene_id":"scene-198","title":"Государственная помощь без контроля","case_key":"bank-legal-2026-148","format":"animated-svg","version":4,"alt":"Государственная помощь без контроля: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Государственная помощь без контроля»: Получатель субсидии выполнил основную работу, но отказался от обязательной отчётности. Куратор предлагает не фиксировать нарушение, чтобы не ухудшать показатель ведомства."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статья 78; условия предоставления субсидии и бюджетного контроля.. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-149","title":"Ненормативный акт против закона","category":"Правовая практика","situation":"Индивидуальный приказ министерства отменил право конкретного заявителя, прямо закреплённое законом. Орган считает, что более поздняя дата приказа даёт ему преимущество.\n\nЗаявитель предъявил норму закона, прямо предоставляющую право при выполненных условиях. Министерство выдало ему индивидуальный приказ об отказе со ссылкой только на более позднюю дату приказа. В приказе не указано изменение закона или иное предусмотренное основание. Участник рассматривает жалобу и должен определить соотношение документов.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Применить акт надлежащей юридической силы; более поздний индивидуальный приказ не отменяет закон, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Применить более поздний индивидуальный приказ вместо закона, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Применить акт надлежащей юридической силы; более поздний индивидуальный приказ не отменяет закон. Основание: Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Применить акт надлежащей юридической силы; более поздний индивидуальный приказ не отменяет закон. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Применить более поздний индивидуальный приказ вместо закона. Надлежащий шаг: Применить акт надлежащей юридической силы; более поздний индивидуальный приказ не отменяет закон. Основание: Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Применить более поздний индивидуальный приказ вместо закона. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статья 15; иерархия правовых актов и судебная защита. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-199","title":"Ненормативный акт против закона","case_key":"bank-legal-2026-149","format":"animated-svg","version":4,"alt":"Ненормативный акт против закона: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Ненормативный акт против закона»: Индивидуальный приказ министерства отменил право конкретного заявителя, прямо закреплённое законом. Орган считает, что более поздняя дата приказа даёт ему преимущество."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статья 15; иерархия правовых актов и судебная защита.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-150","title":"Вознаграждение за обязательную услугу","category":"Правовая практика","situation":"Служащему предложили подарок за ускорение обязательного регистрационного действия. Он считает, что небольшая стоимость делает связь с услугой допустимой.\n\nПосетитель передал служащему подарочную карту на 5 тыс. ₽ и попросил поставить его заявление первым. Регистрационное действие входит в должностные обязанности, очередь уже установлена. Служащий ещё не использовал карту, но предлагает принять её как благодарность. Участник оценивает предложение и порядок дальнейших служебных действий до изменения очереди.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Отказаться от связанного с должностным действием вознаграждения и выполнить установленные обязанности по уведомлению, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Принять связанный с услугой подарок из-за его небольшой стоимости, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Отказаться от связанного с должностным действием вознаграждения и выполнить установленные обязанности по уведомлению. Основание: Федеральный закон № 273-ФЗ; законодательство о государственной службе. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Отказаться от связанного с должностным действием вознаграждения и выполнить установленные обязанности по уведомлению. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 273-ФЗ; законодательство о государственной службе. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 273-ФЗ; законодательство о государственной службе. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 273-ФЗ; законодательство о государственной службе. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 273-ФЗ; законодательство о государственной службе. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Принять связанный с услугой подарок из-за его небольшой стоимости. Надлежащий шаг: Отказаться от связанного с должностным действием вознаграждения и выполнить установленные обязанности по уведомлению. Основание: Федеральный закон № 273-ФЗ; законодательство о государственной службе. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Принять связанный с услугой подарок из-за его небольшой стоимости. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 273-ФЗ; законодательство о государственной службе. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-200","title":"Вознаграждение за обязательную услугу","case_key":"bank-legal-2026-150","format":"animated-svg","version":4,"alt":"Вознаграждение за обязательную услугу: участники изучают инфраструктура и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Вознаграждение за обязательную услугу»: Служащему предложили подарок за ускорение обязательного регистрационного действия. Он считает, что небольшая стоимость делает связь с услугой допустимой."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 273-ФЗ; законодательство о государственной службе.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."}]$authored$::jsonb))
INSERT INTO private.authored_event_catalog(case_key,content)
