FROM private.authored_event_catalog c WHERE e.case_key=c.case_key AND e.case_key IN ('bank-legal-2026-126','bank-legal-2026-127','bank-legal-2026-128','bank-legal-2026-129','bank-legal-2026-130','bank-legal-2026-131','bank-legal-2026-132','bank-legal-2026-133','bank-legal-2026-134','bank-legal-2026-135','bank-legal-2026-136','bank-legal-2026-137','bank-legal-2026-138','bank-legal-2026-139','bank-legal-2026-140','bank-legal-2026-141','bank-legal-2026-142','bank-legal-2026-143','bank-legal-2026-144','bank-legal-2026-145','bank-legal-2026-146','bank-legal-2026-147','bank-legal-2026-148','bank-legal-2026-149','bank-legal-2026-150')
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=e.id);
